ValidationRule.errorConditionFormula:
AND(
NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c &&
OR(
ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c),
CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Account')
)
),
AND(
   OR((ISNEW() && TEXT(Executive_Sponsor__c) != NULL),
   ISCHANGED(Executive_Sponsor__c)), 
NOT(
OR(TEXT(IM_Hierarchy_Level__c) = 'IM Group (IMGA)',
TEXT(IM_Hierarchy_Level__c) = 'Country Parent')
)
)
)
